const routedRoot = $json || {};
if (routedRoot.whatsapp && (routedRoot.router || routedRoot.user || routedRoot.runtime || routedRoot.media)) {
  const whatsapp = routedRoot.whatsapp || {};
  const media = routedRoot.media || {};
  const rawPhone = String(whatsapp.phone || whatsapp.phone_e164 || routedRoot.phone || '').trim();
  const digits = rawPhone.split('@')[0].replace(/\D/g, '');
  const text = String(whatsapp.message_text || routedRoot.message_text || '').trim();
  const messageId = String(whatsapp.message_id || routedRoot.message_id || routedRoot.source?.message_id || '').trim() || (digits ? digits + ':' + Date.now() : 'unknown:' + Date.now());
  return [{ json: {
    ...whatsapp,
    phone: digits,
    remote_jid: whatsapp.remote_jid || (digits ? digits + '@s.whatsapp.net' : ''),
    message_text: text,
    message_id: messageId,
    message_type: whatsapp.message_type || (media.is_pdf ? 'documentMessage' : 'conversation'),
    push_name: whatsapp.push_name || '',
    instance: whatsapp.instance || routedRoot.source?.instance || $env.EVOLUTION_INSTANCE_NAME || '',
    from_me: false,
    is_group: false,
    can_reply: Boolean(digits),
    is_supported_text: Boolean(text || media.is_pdf),
    is_valid_user_message: Boolean(digits && (text || media.is_pdf)),
    current_date: routedRoot.runtime?.current_date || new Date().toLocaleDateString('sv-SE', { timeZone: 'America/Sao_Paulo' }),
    raw: routedRoot,
    user: routedRoot.user || {},
    conversation: routedRoot.conversation || {},
    router: routedRoot.router || {},
    media,
    runtime: routedRoot.runtime || {},
    capabilities: routedRoot.capabilities || []
  }}];
}
const root = $json || {};
const envelope = root.body && typeof root.body === 'object' ? root.body : root;
const data = envelope.data && typeof envelope.data === 'object' ? envelope.data : (root.data || envelope);
const key = data.key || envelope.key || root.key || {};
const msg = data.message || envelope.message || root.message || {};

function onlyDigits(value) {
  return String(value || '').split('@')[0].replace(/\D/g, '');
}

function firstPhone(candidates) {
  for (const candidate of candidates) {
    const digits = onlyDigits(candidate);
    if (digits.length >= 10) return digits;
  }
  return '';
}

const remoteJid = String(
  key.remoteJid ||
  key.remoteJidAlt ||
  data.remoteJid ||
  data.from ||
  envelope.from ||
  root.from ||
  ''
).trim();

const phone = firstPhone([
  key.remoteJid,
  key.remoteJidAlt,
  data.remoteJid,
  data.number,
  envelope.number,
  root.number,
  data.phone,
  envelope.phone,
  root.phone,
  data.sender,
  envelope.sender,
  root.sender
]);

const text = String(
  data.text ||
  envelope.text ||
  root.text ||
  data.bodyText ||
  envelope.bodyText ||
  msg.conversation ||
  msg.extendedTextMessage?.text ||
  msg.imageMessage?.caption ||
  msg.videoMessage?.caption ||
  msg.documentMessage?.caption ||
  msg.buttonsResponseMessage?.selectedDisplayText ||
  msg.listResponseMessage?.title ||
  msg.templateButtonReplyMessage?.selectedDisplayText ||
  ''
).trim();

const messageId = String(
  key.id ||
  data.messageId ||
  data.id ||
  envelope.message_id ||
  root.message_id ||
  root.messageId ||
  root.id ||
  ''
).trim() || `${phone || 'unknown'}:${Date.now()}`;

const fromMe = Boolean(key.fromMe || data.fromMe || envelope.fromMe || root.fromMe);
const messageType = String(data.messageType || envelope.messageType || root.messageType || '').trim();
const instance = String(envelope.instance || data.instance || root.instance || $env.EVOLUTION_INSTANCE_NAME || '').trim();
const isGroup = remoteJid.includes('@g.us');
const canReply = Boolean(phone && !fromMe && !isGroup);
const isSupportedText = Boolean(text);

return [{
  json: {
    phone,
    remote_jid: remoteJid,
    message_text: text,
    message_id: messageId,
    message_type: messageType,
    push_name: data.pushName || envelope.pushName || root.pushName || data.push_name || envelope.push_name || '',
    instance,
    from_me: fromMe,
    is_group: isGroup,
    can_reply: canReply,
    is_supported_text: isSupportedText,
    is_valid_user_message: Boolean(canReply && isSupportedText),
    current_date: new Date().toLocaleDateString('sv-SE', { timeZone: 'America/Sao_Paulo' }),
    raw: root
  }
}];

const root = $json || {};
const whatsapp = root.whatsapp && typeof root.whatsapp === 'object' ? root.whatsapp : {};
const text = String(root.outbound_text || whatsapp.text || root.message || root.reply_text || root.clarifying_question || "Ainda não consigo ler esse tipo de mensagem por aqui. Me manda em texto? Se for fatura, pode enviar o PDF.").trim();
return [{ json: { ...root, ok: root.ok !== false, workflow_key: root.workflow_key || "1.1", outbound_text: text, send_by_orchestrator: true, whatsapp: { ...whatsapp, text } } }];

const normalized = $('Normalize Evolution Payload').first().json || {};
const root = normalized.raw || $json || {};
const user = normalized.user || root.user || {};
const conversation = normalized.conversation || root.conversation || {};
const authorized = user.authorized !== false && Number(user.id || 0) > 0;
return [{ json: { ...root, authorized, code: authorized ? 'AUTHORIZED_BY_ORCHESTRATOR' : 'NOT_AUTHORIZED', user, conversation, phone: normalized.phone, whatsapp: { ...(root.whatsapp || {}), phone: normalized.phone, message_text: normalized.message_text, message_id: normalized.message_id, instance: normalized.instance } } }];

const root = $json || {};
const whatsapp = root.whatsapp && typeof root.whatsapp === 'object' ? root.whatsapp : {};
const text = String(root.outbound_text || whatsapp.text || root.message || root.reply_text || root.clarifying_question || "Esse número ainda não está liberado no AcerttaPay. Ative o WhatsApp nas Configurações do app.").trim();
return [{ json: { ...root, ok: root.ok !== false, workflow_key: root.workflow_key || "1.1", outbound_text: text, send_by_orchestrator: true, whatsapp: { ...whatsapp, text } } }];

function cleanJsonContent(value) {
  if (value && typeof value === 'object') return value;
  const raw = String(value || '').trim();
  if (!raw) return '';
  const withoutFence = raw.replace(/^```(?:json)?\s*/i, '').replace(/```$/i, '').trim();
  const first = withoutFence.indexOf('{');
  const last = withoutFence.lastIndexOf('}');
  if (first >= 0 && last > first) return withoutFence.slice(first, last + 1);
  return withoutFence;
}

const fallbackHelp = 'Posso te ajudar a registrar uma compra no cartão. 🧾\n\nMe manda assim:\n• *Nova compra hoje de R$ 199,90 em Casas Bahia*\n• *Comprei ontem R$ 45,00 no iFood*\n• *Compra de R$ 300,00 em 3x na Amazon*\n\nSe faltar algo, eu pergunto antes de lançar. Sem chute na fatura. 😉';
const content = $json.output ?? $json.text ?? $json.response ?? $json.choices?.[0]?.message?.content ?? '';
let parsed;
try {
  const cleaned = cleanJsonContent(content);
  parsed = typeof cleaned === 'object' ? cleaned : JSON.parse(cleaned);
} catch (error) {
  parsed = {
    intent: 'clarification',
    confidence: 0,
    needs_clarification: true,
    reply_text: fallbackHelp,
    clarifying_question: fallbackHelp,
    purchase: null
  };
}

if (!parsed || typeof parsed !== 'object') {
  parsed = {
    intent: 'clarification',
    confidence: 0,
    needs_clarification: true,
    reply_text: fallbackHelp,
    clarifying_question: fallbackHelp,
    purchase: null
  };
}

parsed.intent = String(parsed.intent || 'clarification').trim();
parsed.confidence = Number(parsed.confidence || 0);
parsed.needs_clarification = parsed.needs_clarification === true;

if (parsed.purchase && typeof parsed.purchase === 'object') {
  parsed.purchase.amount_cents = Number(parsed.purchase.amount_cents || 0);
  parsed.purchase.installments = Math.max(1, Number(parsed.purchase.installments || 1) || 1);
  parsed.purchase.is_recurring = parsed.purchase.is_recurring === true;
  parsed.purchase.card_hint = parsed.purchase.card_hint || parsed.purchase.cardHint || null;
} else {
  parsed.purchase = null;
}

const hasCompletePurchase = Boolean(
  parsed.intent === 'create_purchase' &&
  parsed.needs_clarification !== true &&
  parsed.purchase &&
  parsed.purchase.amount_cents > 0 &&
  parsed.purchase.description &&
  parsed.purchase.date
);

if (!hasCompletePurchase) {
  parsed.reply_text = parsed.reply_text || parsed.clarifying_question || fallbackHelp;
}

parsed.should_create_purchase = hasCompletePurchase;
return [{ json: parsed }];

const root = $json || {};
const whatsapp = root.whatsapp && typeof root.whatsapp === 'object' ? root.whatsapp : {};
const text = String(root.outbound_text || whatsapp.text || root.message || root.reply_text || root.clarifying_question || "Pedido processado no AcerttaPay.").trim();
return [{ json: { ...root, ok: root.ok !== false, workflow_key: root.workflow_key || "1.1", outbound_text: text, send_by_orchestrator: true, whatsapp: { ...whatsapp, text } } }];

const root = $json || {};
const whatsapp = root.whatsapp && typeof root.whatsapp === 'object' ? root.whatsapp : {};
const text = String(root.outbound_text || whatsapp.text || root.message || root.reply_text || root.clarifying_question || "Pedido processado no AcerttaPay.").trim();
return [{ json: { ...root, ok: root.ok !== false, workflow_key: root.workflow_key || "1.1", outbound_text: text, send_by_orchestrator: true, whatsapp: { ...whatsapp, text } } }];

function cleanJsonContent(value) {
  if (value && typeof value === 'object') return value;
  const raw = String(value || '').trim();
  if (!raw) return '';
  const withoutFence = raw.replace(/^```(?:json)?\s*/i, '').replace(/```$/i, '').trim();
  const first = withoutFence.indexOf('{');
  const last = withoutFence.lastIndexOf('}');
  if (first >= 0 && last > first) return withoutFence.slice(first, last + 1);
  return withoutFence;
}

const content = $json.output ?? $json.text ?? $json.response ?? $json.choices?.[0]?.message?.content ?? '';
let parsed;
try {
  const cleaned = cleanJsonContent(content);
  parsed = typeof cleaned === 'object' ? cleaned : JSON.parse(cleaned);
} catch (error) {
  parsed = {
    intent: 'clarification',
    confidence: 0,
    raw_text: $('Normalize Evolution Payload').first().json.message_text
  };
}

if (!parsed || typeof parsed !== 'object') {
  parsed = {
    intent: 'clarification',
    confidence: 0,
    raw_text: $('Normalize Evolution Payload').first().json.message_text
  };
}

if (Array.isArray(parsed.shares)) {
  parsed.shares = parsed.shares.map((share) => ({
    ...share,
    amount_cents: Number(share.amount_cents || 0)
  }));
}

return [{ json: parsed }];

const root = $json || {};
const whatsapp = root.whatsapp && typeof root.whatsapp === 'object' ? root.whatsapp : {};
const text = String(root.outbound_text || whatsapp.text || root.message || root.reply_text || root.clarifying_question || "Pedido processado no AcerttaPay.").trim();
return [{ json: { ...root, ok: root.ok !== false, workflow_key: root.workflow_key || "1.1", outbound_text: text, send_by_orchestrator: true, whatsapp: { ...whatsapp, text } } }];

function brl(cents) {
  const value = Number(cents || 0) / 100;
  return value.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' }).replace(/\u00A0/g, ' ');
}

function pad2(value) {
  return String(value || '').padStart(2, '0');
}

function linesClean(lines) {
  return lines.filter((line) => line !== null && line !== undefined).join('\n').replace(/\n{3,}/g, '\n\n').trim();
}

function cardList(cards = []) {
  return cards.map((card, index) => `${card.option || index + 1}. *${card.label || card.name || `Cartão ${index + 1}`}*`).join('\n');
}

const res = $json || {};
const code = String(res.code || '').trim();
const p = res.purchase || {};
const backend = res.whatsapp?.text || res.message || '';
let outboundText = backend;

if (code === 'PURCHASE_CREATED') {
  const rows = [
    '✅ *Compra registrada com sucesso!*',
    '',
    '🧾 *Resumo da compra*',
    '━━━━━━━━━━━━━━━━',
    p.description ? `🏬 Descrição: *${p.description}*` : null,
    p.amount_cents ? `💰 Valor: *${brl(p.amount_cents)}*` : null,
    p.installments && Number(p.installments) > 1 ? `🔢 Parcelas: *${p.installments}x*` : '🔢 Parcelas: *1x*',
    p.card_name ? `💳 Cartão: *${p.card_name}*` : null,
    p.due_month && p.due_year ? `🗓️ Fatura: *${pad2(p.due_month)}/${p.due_year}*` : null,
    p.is_recurring ? '🔁 Recorrência: *sim*' : null,
    p.id ? `🔖 Código: *#${p.id}*` : null,
    '',
    'Quer definir os participantes dessa compra?',
    'Responde *sim* para dividir ou *não* para deixar só com você.'
  ];
  outboundText = linesClean(rows);
} else if (code === 'NEEDS_CARD_CONFIRMATION') {
  const card = res.card || res.conversation?.payload?.suggested_card || {};
  const label = card.label || card.name || 'cartão informado';
  outboundText = linesClean([
    '💳 *Esse foi o cartão da compra?*',
    '',
    `Pelo que entendi, entrou no *${label}*.`,
    '',
    'Responde *sim* para confirmar ou *não* para escolher outro cartão.'
  ]);
} else if (code === 'NEEDS_CARD_SELECTION') {
  outboundText = linesClean([
    '💳 *Qual cartão entrou nessa compra?*',
    '',
    cardList(res.cards || []),
    '',
    'Me responde com o *número* ou o *nome* do cartão. Sem chute na fatura. 😉'
  ]);
} else if (code === 'NO_ACTIVE_CARD') {
  outboundText = '💳 Não encontrei cartão ativo para lançar essa compra.\n\nCrie ou reative um cartão no AcerttaPay e me chama de novo que eu registro sem bagunça.';
} else if (code === 'MONTH_CLOSED') {
  outboundText = '🔒 Essa fatura já foi fechada.\n\nNão mexi nela para não bagunçar o que já foi pago.';
} else if (code === 'DUPLICATE_MESSAGE' || res.duplicate === true) {
  outboundText = backend || 'Essa mensagem já passou por aqui. Não dupliquei a compra, sua fatura agradece. ✅';
} else if (!outboundText) {
  outboundText = 'Pedido recebido no AcerttaPay. Segui por aqui sem fazer malabarismo financeiro.';
}

return [{ json: { ...res, outbound_text: outboundText } }];

function brl(cents) {
  const value = Number(cents || 0) / 100;
  return value.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' }).replace(/\u00A0/g, ' ');
}

function pad2(value) {
  return String(value || '').padStart(2, '0');
}

function linesClean(lines) {
  return lines.filter((line) => line !== null && line !== undefined).join('\n').replace(/\n{3,}/g, '\n\n').trim();
}

function optionName(option, index) {
  return `${option.option || index + 1}. *${option.label || option.name || `Opção ${index + 1}`}*`;
}

function optionList(options = []) {
  return options.map((option, index) => optionName(option, index)).join('\n');
}

function groupedOptionList(options = []) {
  const rows = Array.isArray(options) ? options : [];
  const self = rows.filter((option) => option.is_self || String(option.id) === 'self');
  const shared = rows.filter((option) => !(option.is_self || String(option.id) === 'self') && (option.can_create_shared_debt === true || option.can_share_charge === true || option.group === 'shared_debt'));
  const local = rows.filter((option) => !(option.is_self || String(option.id) === 'self') && !(option.can_create_shared_debt === true || option.can_share_charge === true || option.group === 'shared_debt'));
  const lines = [];
  if (self.length) lines.push('🙋 *Você*', optionList(self));
  if (shared.length) lines.push(lines.length ? '' : null, '🤝 *Amigos com Acerto disponível*', optionList(shared));
  if (local.length) lines.push(lines.length ? '' : null, '📝 *Contatos locais*', optionList(local));
  return linesClean(lines);
}

const res = $json || {};
const code = String(res.code || '').trim();
const p = res.purchase || {};
const backend = res.whatsapp?.text || res.message || '';
let outboundText = backend;

if (code === 'PURCHASE_CREATED') {
  outboundText = linesClean([
    '✅ *Compra registrada com sucesso!*',
    '',
    '🧾 *Resumo da compra*',
    '━━━━━━━━━━━━━━━━',
    p.description ? `🏬 Descrição: *${p.description}*` : null,
    p.amount_cents ? `💰 Valor: *${brl(p.amount_cents)}*` : null,
    p.installments && Number(p.installments) > 1 ? `🔢 Parcelas: *${p.installments}x*` : '🔢 Parcelas: *1x*',
    p.card_name ? `💳 Cartão: *${p.card_name}*` : null,
    p.due_month && p.due_year ? `🗓️ Fatura: *${pad2(p.due_month)}/${p.due_year}*` : null,
    p.id ? `🔖 Código: *#${p.id}*` : null,
    '',
    'Quer definir os participantes dessa compra?',
    'Responde *sim* para dividir ou *não* para deixar só com você.'
  ]);
} else if (code === 'NEEDS_CARD_CONFIRMATION') {
  const card = res.card || res.conversation?.payload?.suggested_card || {};
  const label = card.label || card.name || 'cartão informado';
  outboundText = linesClean([
    '💳 *Esse foi o cartão da compra?*',
    '',
    `Pelo que entendi, entrou no *${label}*.`,
    '',
    'Responde *sim* para confirmar ou *não* para escolher outro cartão.'
  ]);
} else if (code === 'NEEDS_CARD_SELECTION') {
  outboundText = linesClean([
    '💳 *Qual cartão entrou nessa compra?*',
    '',
    optionList(res.cards || []),
    '',
    'Pode responder com o *número* ou com o *nome* do cartão.'
  ]);
} else if (code === 'NEEDS_SPLIT_CONFIRMATION') {
  outboundText = '👥 Quer definir participantes para essa compra?\n\nResponde *sim* para dividir ou *não* para deixar só com você.';
} else if (code === 'NEEDS_SPLIT_PARTICIPANTS') {
  outboundText = linesClean([
    '👥 *Com quem vamos dividir?*',
    '',
    groupedOptionList(res.options || []),
    '',
    'Pode responder:',
    '• *Apenas eu*',
    '• *Eu, Ana e Bruno*',
    '• *Ana e Bruno*',
    '',
    'Se você quiser entrar no rateio, escreva *Eu* na resposta.',
    '',
    '📝 Contatos locais entram no seu controle interno. Só amigos com Acerto disponível geram rascunho na Central de Acertos.'
  ]);
} else if (code === 'NEEDS_SPLIT_MODE') {
  outboundText = '⚖️ Como vamos dividir essa compra?\n\n1. *Partes iguais*\n2. *Valores definidos*\n\nMe responde com uma das opções e eu fecho a conta sem arredondamento freestyle.';
} else if (code === 'NEEDS_EXACT_AMOUNTS') {
  outboundText = '💰 Me manda quanto fica para cada pessoa.\n\nEx.: *Eu 99,90, Ana 50, Bruno 50*\n\nA soma precisa bater certinho com o valor da compra.';
} else if (code === 'SPLIT_SKIPPED') {
  outboundText = 'Fechado, deixei essa compra só com você. 🧾\n\nLance solo confirmado, sem plateia no boleto. ✅';
} else if (code === 'SPLIT_APPLIED') {
  const queueCount = Number(res.split?.queue_summary?.itemCount || 0);
  outboundText = queueCount > 0
    ? `✅ *Divisão salva!*\n\n${queueCount} item(ns) ficaram em rascunho na *Central de Acertos*. Não enviei nada automaticamente, porque dinheiro combinado vale mais que pressa.`
    : '✅ *Divisão salva!*\n\nTudo redondinho por aqui. Se tiver contato local na divisão, ele ficou registrado só para seu controle interno.';
} else if (code === 'NO_PENDING_CONVERSATION') {
  outboundText = 'Esse papo ficou sem contexto por aqui. 😅\n\nMe manda a compra completa para começarmos de novo.';
} else if (!outboundText) {
  outboundText = 'Conversa atualizada no AcerttaPay. Segui sem inventar moda financeira.';
}

return [{ json: { ...res, outbound_text: outboundText } }];
